import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
  JxBadgeTone,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'warning' | 'over' | 'closed';

interface Project {
  id: string;
  name: string;
  status: ProjectStatus;
  used: number;
  quota: number;
}

const STATUS_META: Record<ProjectStatus, { label: string; tone: JxBadgeTone }> = {
  active: { label: 'В работе', tone: 'success' },
  warning: { label: 'Близко к лимиту', tone: 'warning' },
  over: { label: 'Превышен лимит', tone: 'danger' },
  closed: { label: 'Закрыт', tone: 'default' },
};

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Редизайн лендинга', status: 'active', used: 42, quota: 100 },
  { id: 'p2', name: 'Миграция биллинга', status: 'warning', used: 87, quota: 100 },
  { id: 'p3', name: 'Мобильное приложение', status: 'over', used: 118, quota: 100 },
  { id: 'p4', name: 'Внутренняя аналитика', status: 'active', used: 15, quota: 100 },
  { id: 'p5', name: 'Поддержка legacy API', status: 'closed', used: 100, quota: 100 },
  { id: 'p6', name: 'Онбординг клиентов', status: 'active', used: 60, quota: 100 },
  { id: 'p7', name: 'Интеграция с CRM', status: 'warning', used: 91, quota: 100 },
  { id: 'p8', name: 'Тестовый стенд QA', status: 'closed', used: 30, quota: 100 },
  { id: 'p9', name: 'Аудит безопасности', status: 'over', used: 130, quota: 100 },
  { id: 'p10', name: 'Обновление дизайн-системы', status: 'active', used: 24, quota: 100 },
  { id: 'p11', name: 'Каталог продуктов', status: 'warning', used: 78, quota: 100 },
  { id: 'p12', name: 'Экспорт отчётов', status: 'active', used: 8, quota: 100 },
];

const STATUS_ORDER: ProjectStatus[] = ['active', 'warning', 'over', 'closed'];
const PAGE_SIZE = 5;

export default function ProjectSpendingPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]
    );
    setPage(1);
  };

  const removeStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) => prev.filter((s) => s !== status));
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses([]);
    setPage(1);
  };

  const filtered = useMemo(() => {
    if (activeStatuses.length === 0) return PROJECTS;
    return PROJECTS.filter((p) => activeStatuses.includes(p.status));
  }, [activeStatuses]);

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const visible = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 16,
        padding: 20,
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        fontFamily: 'var(--jx-font-sans)',
        maxWidth: 640,
      }}
    >
      <div>
        <h2
          style={{
            margin: 0,
            marginBottom: 4,
            fontSize: 18,
            color: 'var(--jx-text)',
          }}
        >
          Расход по проектам
        </h2>
        <p style={{ margin: 0, fontSize: 13, color: 'var(--jx-text-2)' }}>
          Фильтруйте проекты по статусу квоты
        </p>
      </div>

      <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
        {STATUS_ORDER.map((status) => {
          const isActive = activeStatuses.includes(status);
          return (
            <JxChip
              key={status}
              active={isActive}
              removable={isActive}
              onRemove={isActive ? () => removeStatus(status) : undefined}
              onClick={() => toggleStatus(status)}
            >
              {STATUS_META[status].label}
            </JxChip>
          );
        })}
      </div>

      {visible.length === 0 ? (
        <JxEmptyState
          title="Проекты не найдены"
          message="Под выбранные фильтры не попал ни один проект. Сбросьте фильтры, чтобы увидеть весь список."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
            {visible.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: 12,
                  padding: '12px 8px',
                  borderBottom: '1px solid var(--jx-rule)',
                }}
              >
                <span
                  style={{
                    color: 'var(--jx-text)',
                    fontSize: 14,
                    flex: 1,
                    minWidth: 0,
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    whiteSpace: 'nowrap',
                  }}
                >
                  {project.name}
                </span>

                <JxProgressCircle
                  value={Math.min(project.used, project.quota)}
                  max={project.quota}
                  showValue
                />

                <JxBadge tone={STATUS_META[project.status].tone} dot>
                  {STATUS_META[project.status].label}
                </JxBadge>
              </div>
            ))}
          </div>

          <div style={{ display: 'flex', justifyContent: 'center' }}>
            <JxPagination total={pageCount} page={page} onPageChange={setPage} />
          </div>
        </>
      )}
    </div>
  );
}

